llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Fenofibrate, the most similar retrieved analogue, has an oral bioavailability of approximately 30% in humans, above the 20% threshold; this supports that the query's lipophilic heteroaromatic scaffold is compatible with F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Vismodegib, an oral anticancer drug with an aryl amide and heteroaromatic core, has a measured absolute oral bioavailability of 31.8% in humans, directly above the threshold; this supports a high-F prediction for the query, which shares similar drug-like amide/heteroaromatic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Sorafenib, a multi-kinase inhibitor with an aryl amide and heteroaromatic structure, has reported absolute oral bioavailability of 38–49% in patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "CJ-13,610, a heteroaryl thioether amide, showed 47% bioavailability from intravenous and oral clinical studies in humans, supporting high F for the query's thioether-benzamide motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Belumosudil, a kinase inhibitor with an amide and heteroaromatic core, has an absolute oral bioavailability of 64% after a 200 mg oral dose in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "One sorafenib record reports approximately 8.5% oral bioavailability, which would be below the threshold; however, this is an outlier contradicted by multiple other sorafenib absolute bioavailability estimates of 38–50% and does not outweigh the consistent high-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F ≥ 20%). The query is axitinib, a VEGFR inhibitor with known oral bioavailability around 58%; the retrieved analogues—fenofibrate (~30%), vismodegib (31.8%), sorafenib (38–49%), CJ-13,610 (47%), and belumosudil (64%)—consistently show moderate-to-high oral bioavailability, and no reliable sub-threshold evidence transfers to the query.",
  "evidence_gaps": [
    "No direct axitinib bioavailability measurement is present in the evidence set; all analogues have low Morgan similarity (<0.26).",
    "The only sub-threshold record (sorafenib 8.5%) is an outlier and not mechanistically explained.",
    "Some records do not explicitly distinguish absolute from relative bioavailability, adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

